  "implementation": "def solve(case):
    import json
    payload = case['payload']
    nodes = payload['nodes']
    core_distance = payload['core_distance']
    distances = payload['distances']

    # Build mutual reachability edges
    edges = []  # (weight, a, b)
    for a, b, d in distances:
        if a > b:
            a, b = b, a
        w = max(core_distance[a], core_distance[b], d)
        edges.append((w, a, b))

    # Sort: primary weight, then node a, then node b
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    tree_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            tree_edges.append([a, b, w])
            total_weight += w
            if len(tree_edges) == len(nodes) - 1:
                break

    if len(tree_edges) != len(nodes) - 1:
        raise ValueError('Disconnected graph: cannot form a spanning tree')

    return {'tree_edges': tree_edges, 'total_weight': total_weight}"
}
